// Metal Shading Language (as generated by SPIRV-Cross / bgfx shaderc) -> GLSL 4.60 translator.
//
// The game's shaders (renderer/materials/*.material.bin) contain MSL source text. Each
// entry point is translated once into a stage-independent intermediate form (the GLSL
// body plus its interface), and combined into a GL program when a pipeline is created
// (msl::emit_stage), where the bindings of the stage are known.
#pragma once
#include <memory>
#include <string>
#include <vector>

namespace msl {

enum class Stage { Vertex, Fragment, Kernel };

// MTLDataType values (reflection)
enum DataType : unsigned {
    DT_None = 0, DT_Struct = 1, DT_Array = 2, DT_Float = 3, DT_Float2 = 4, DT_Float3 = 5, DT_Float4 = 6,
    DT_Float2x2 = 7, DT_Float2x3 = 8, DT_Float2x4 = 9, DT_Float3x2 = 10, DT_Float3x3 = 11, DT_Float3x4 = 12,
    DT_Float4x2 = 13, DT_Float4x3 = 14, DT_Float4x4 = 15, DT_Half = 16, DT_Int = 29, DT_Int2 = 30, DT_Int3 = 31,
    DT_Int4 = 32, DT_UInt = 33, DT_UInt2 = 34, DT_UInt3 = 35, DT_UInt4 = 36, DT_Bool = 53, DT_Texture = 58,
    DT_Sampler = 59,
};

struct Member {  // reflection of a constant buffer member (MSL layout)
    std::string name;
    unsigned offset = 0, size = 0;
    unsigned data_type = 0;   // DataType of the element
    unsigned array_len = 0;   // 0 = not an array
    unsigned stride = 0;
};

struct BufferArg {
    std::string name;       // parameter name (e.g. _mtl_u)
    unsigned index = 0;     // [[buffer(n)]]
    bool writable = false;  // device (not const)
    bool is_struct = true;
    unsigned size = 0;      // struct size
    std::vector<Member> members;
};

struct TextureArg {
    std::string name;
    unsigned index = 0;
    unsigned mtl_type = 2;  // MTLTextureType
    char component = 'f';   // f / i / u
    bool image = false;     // access::read_write / write (compute)
    int sampler = -1;       // [[sampler(n)]] used to sample it (-1 = none / read only)
    int image_unit = -1;    // GL image unit (images)
};

struct SamplerArg {
    std::string name;
    unsigned index = 0;
};

struct Varying {
    unsigned location = 0;
    std::string name;    // MSL member name (vertex attributes: a_position, ...)
    std::string type;    // GLSL type
    std::string interp;  // "", "flat", "noperspective", "centroid", "sample"
};

struct Function {
    std::string name;
    Stage stage = Stage::Vertex;
    std::string body;     // GLSL: helper declarations + main(); bindings are placeholders (@B<n>@, @T<n>@)
    std::string error;    // non-empty when the translation failed
    std::vector<BufferArg> buffers;
    std::vector<TextureArg> textures;
    std::vector<SamplerArg> samplers;
    std::vector<Varying> inputs;   // vertex: attributes; fragment: varyings
    std::vector<Varying> outputs;  // vertex: varyings; fragment: color outputs
    bool uses_point_size = false;
};

struct Library {
    std::vector<std::shared_ptr<Function>> functions;
    std::string error;
};

// Parses and translates every entry point (vertex / fragment / kernel) of the source.
std::shared_ptr<Library> translate(const std::string& source);

// Final GLSL of one stage. Binding of buffer index n = buffer_base + n, texture index n =
// texture_base + n. `other` (fragment: the vertex function) completes the interface.
// Kernels: local_size = threads per threadgroup.
std::string emit_stage(const Function& f, unsigned buffer_base, unsigned texture_base, const Function* other,
                       unsigned lx = 1, unsigned ly = 1, unsigned lz = 1);

}  // namespace msl
